                                            .truststorePath(System.getenv("TRUST_PATH"))
                                            .keystorePassword(System.getenv("KEY_PASSWORD"))
                                            .keystoreType("PKCS12")
                                            .keystorePath(System.getenv("KEY_PATH"))
                                            .build())
                                    .build())
                            .build())
